-- Feedback from the Feedback button (docs/plan.md §1.8) and the log of the operator's client
-- setting changes that need a reason (tenant_change; first use: the feedback switch). New tables
-- only, so the previous Worker keeps working. Generated by drizzle-kit; the grants, row-level
-- security and append-only trigger at the end are hand-written, as in 0002 and 0004.
CREATE TABLE "feedback" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid,
	"surface" text NOT NULL,
	"user_id" uuid NOT NULL,
	"comment" text NOT NULL,
	"path" text NOT NULL,
	"viewport" jsonb NOT NULL,
	"pin" jsonb,
	"target" text,
	"screenshot_key" text,
	"screenshot_bytes" integer,
	"status" text DEFAULT 'open' NOT NULL,
	"resolved_at" timestamp with time zone,
	"resolved_by" uuid,
	"resolution_note" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "feedback_surface_check" CHECK ("feedback"."surface" in ('ops', 'portal')),
	CONSTRAINT "feedback_status_check" CHECK ("feedback"."status" in ('open', 'resolved')),
	CONSTRAINT "feedback_surface_tenant_check" CHECK (("feedback"."surface" = 'portal') = ("feedback"."tenant_id" is not null))
);
